def solve(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    rem={(i,j) for i in range(H) for j in range(W) if g[i][j]}
    cmap={(0,0):2,(1,0):3,(0,1):4}
    while rem:
        i,j=min(rem)
        placed=False
        for di,dj in [(0,0),(0,-1),(-1,0),(-1,-1)]:
            top,left=i+di,j+dj
            if not(0<=top<H-1+1 and 0<=top<=H-2 and 0<=left<=W-2): continue
            win=[(top+a,left+b) for a in range(2) for b in range(2)]
            pres=[c for c in win if c in rem]
            miss=[c for c in win if c not in rem]
            if len(pres)==4:
                for c in win: out[c[0]][c[1]]=1; rem.discard(c)
                placed=True;break
            if len(pres)==3 and len(miss)==1 and miss[0] in [(top,left),(top+1,left),(top,left+1)]:
                # missing corner must be background (0), not another tile
                m=miss[0]
                if g[m[0]][m[1]]!=0: continue
                col=cmap[(m[0]-top,m[1]-left)]
                for c in pres: out[c[0]][c[1]]=col; rem.discard(c)
                placed=True;break
        if not placed: return None,'stuck at %s,%s'%(i,j)
    return out,'ok'

