import json
def tilings(g):
    H,W=len(g),len(g[0])
    cells={(i,j) for i in range(H) for j in range(W) if g[i][j]}
    cmap={(0,0):2,(1,0):3,(0,1):4}
    res=[]
    def rec(rem,acc):
        if not rem: res.append(acc); return
        i,j=min(rem)
        for top in (i,i-1):
            for left in (j,j-1):
                if top<0 or left<0 or top+1>=H or left+1>=W: continue
                win=[(top+a,left+b) for a in range(2) for b in range(2)]
                pres=[c for c in win if c in rem]
                if len(pres)==4:
                    rec(rem-set(win),acc+[(c,1) for c in win])
                elif len(pres)==3:
                    m=[c for c in win if c not in pres][0]
                    if g[m[0]][m[1]]==0:
                        col=cmap[(m[0]-top,m[1]-left)]
                        rec(rem-set(pres),acc+[(c,col) for c in pres])
        return
    rec(cells,[])
    return res

