def tilings(g):
    H,W=len(g),len(g[0])
    cells={(i,j) for i in range(H) for j in range(W) if g[i][j]}
    # L shapes: 2x2 minus one corner; missing corner (dr,dc) -> color
    cmap={(0,0):2,(1,0):3,(0,1):4,(1,1):5}
    res=[]
    def rec(rem,acc):
        if not rem: res.append(dict(acc)); return
        i,j=min(rem)
        # square
        sq=[(i+a,j+b) for a in range(2) for b in range(2)]
        if i+1<H and j+1<W and all(c in rem for c in sq):
            rec(rem-set(sq),acc+[(c,1) for c in sq])
        for (mr,mc),col in cmap.items():
            l=[(i+a,j+b) for a in range(2) for b in range(2) if (a,b)!=(mr,mc)]
            if i+1<H and j+1<W and all(c in rem for c in l):
                rec(rem-set(l),acc+[(c,col) for c in l])
    rec(cells,[])
    return res

